// LoadUpdatedByUserUser loads the gameServerSecret's UpdatedByUserUser into the .R struct
func (os GameServerSecretSlice) LoadUpdatedByUserUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.UpdatedByUserUser(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.UpdatedByUserUser = nil
		o.R.Loaded.UpdatedByUserUser = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	gameServerSecretByKey := make(map[string][]*GameServerSecret, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.UpdatedByUserID.IsValue() {
			continue
		}

		gameServerSecretByKey[o.UpdatedByUserID.MustGet()] = append(gameServerSecretByKey[o.UpdatedByUserID.MustGet()], o)
	}

	for _, rel := range users {

		owners, ok := gameServerSecretByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.UpdatedByUserUser != nil {
				continue
			}

			rel.R.UpdatedByUserGameServerSecrets = append(rel.R.UpdatedByUserGameServerSecrets, o)

			o.R.UpdatedByUserUser = rel

		}
	}

	return nil
}

